import {MAPS} from './maps.js';
const $=s=>document.querySelector(s);let game=null,mapId='north',weaponId='vx7',view='menu',lastState=null;
const input={forward:0,right:0,fire:false,aim:false,sprint:false};const keys=new Set();let joy={forward:0,right:0};let audio=null,noise=null;let markerTimer,damageTimer;
function setScreen(name){view=name;$('#menu').hidden=name!=='menu';$('#hud').hidden=!['playing','paused','respawn'].includes(name);$('#pause-screen').hidden=name!=='paused';$('#results').hidden=name!=='finished';}
function preview(){const m=MAPS[mapId];$('#preview-name').innerHTML=(mapId==='north'?'NORD<br>CAMPUS':'SÜD<br>CAMPUS')+'<span>120 SEK / KONTROLLPUNKT</span>';$('#map-code').textContent=mapId==='north'?'SEKTOR N / 01':'SEKTOR S / 02';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','-56 -56 112 112');svg.innerHTML='<rect x="-50" y="-50" width="100" height="100" fill="#27392e" stroke="#97ad8290" stroke-width=".3"/><path d="M-50 0H50 M0-50V50" stroke="#7c8d75" stroke-width="1" stroke-dasharray="2 2"/>';for(const b of m.boxes){const r=document.createElementNS(svg.namespaceURI,'rect');r.setAttribute('x',b.x-b.w/2);r.setAttribute('y',b.z-b.d/2);r.setAttribute('width',b.w);r.setAttribute('height',b.d);r.setAttribute('fill','#'+b.color.toString(16).padStart(6,'0'));r.setAttribute('stroke','#dce8c8');r.setAttribute('stroke-width','.3');svg.append(r)}const o=document.createElementNS(svg.namespaceURI,'circle');o.setAttribute('cx',m.objective.x);o.setAttribute('cy',m.objective.z);o.setAttribute('r',m.objective.radius||6);o.setAttribute('fill','#d5dc6230');o.setAttribute('stroke','#d5dc62');o.setAttribute('stroke-width','.6');svg.append(o);$('#map-preview').replaceChildren(svg)}
document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{mapId=b.dataset.map;document.querySelectorAll('[data-map]').forEach(x=>x.classList.toggle('selected',x===b));preview()});document.querySelectorAll('[data-weapon]').forEach(b=>b.onclick=()=>{weaponId=b.dataset.weapon;document.querySelectorAll('[data-weapon]').forEach(x=>x.classList.toggle('selected',x===b))});preview();
function ensureAudio(){try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();if(!noise){noise=audio.createBuffer(1,audio.sampleRate*.1,audio.sampleRate);const a=noise.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*(1-i/a.length)}}catch{}}
function sound(type){if(!audio||audio.state!=='running')return;const now=audio.currentTime,g=audio.createGain();g.connect(audio.destination);if(type==='shoot'){const n=audio.createBufferSource();n.buffer=noise;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1600;n.connect(filter);filter.connect(g);g.gain.setValueAtTime(.16,now);g.gain.exponentialRampToValueAtTime(.001,now+.095);n.start();n.stop(now+.1)}else if(['hit','kill','reload'].includes(type)){const osc=audio.createOscillator();osc.type='triangle';osc.frequency.setValueAtTime(type==='kill'?1000:type==='hit'?700:280,now);osc.connect(g);g.gain.setValueAtTime(.035,now);g.gain.exponentialRampToValueAtTime(.001,now+.09);osc.start();osc.stop(now+.1)}}
function send(){input.forward=Math.max(-1,Math.min(1,joy.forward+(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0)));input.right=Math.max(-1,Math.min(1,joy.right+(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0)));game?.setInput(input)}
function release(){keys.clear();joy={forward:0,right:0};Object.assign(input,{forward:0,right:0,fire:false,aim:false,sprint:false});$('#aim').classList.remove('active');$('#sprint').classList.remove('active');$('#stick').style.transform='';send()}
function start(){if(!game)return;release();ensureAudio();setScreen('playing');$('#arena-name').textContent=MAPS[mapId].name.toUpperCase();try{game.start(mapId,weaponId)}catch(e){setScreen('menu');$('#boot-status').textContent='Start fehlgeschlagen: '+e.message;$('#boot-status').classList.add('error');console.error(e)}}
function pause(){if(!game||!['playing','respawn'].includes(view))return;game.pause();release();setScreen('paused')}
function back(){game?.pause();release();setScreen('menu')}
$('#start').onclick=start;$('#pause').onclick=pause;$('#resume').onclick=()=>{game?.resume();setScreen(lastState?.phase==='respawn'?'respawn':'playing')};$('#back-menu').onclick=back;$('#select-map').onclick=back;$('#again').onclick=start;$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();
const pad=$('#joystick');let joyPointer=null;
function moveStick(e){const rect=pad.getBoundingClientRect(),dx=e.clientX-rect.left-rect.width/2,dy=e.clientY-rect.top-rect.height/2,max=rect.width*.34,len=Math.max(max,Math.hypot(dx,dy));joy={right:dx/len,forward:-dy/len};$('#stick').style.transform=`translate(${dx/len*max}px,${dy/len*max}px)`;send()}
pad.onpointerdown=e=>{if(view!=='playing')return;e.preventDefault();joyPointer=e.pointerId;pad.setPointerCapture(e.pointerId);moveStick(e)};pad.onpointermove=e=>{if(e.pointerId===joyPointer)moveStick(e)};function stopStick(e){if(e.pointerId!==joyPointer)return;joyPointer=null;joy={forward:0,right:0};$('#stick').style.transform='';send()}pad.onpointerup=pad.onpointercancel=pad.onlostpointercapture=stopStick;
const look=$('#look-zone');let lookPointer=null,lookLast=null;look.onpointerdown=e=>{if(view!=='playing')return;e.preventDefault();lookPointer=e.pointerId;lookLast={x:e.clientX,y:e.clientY};look.setPointerCapture(e.pointerId)};look.onpointermove=e=>{if(e.pointerId!==lookPointer||!lookLast)return;game?.look(e.clientX-lookLast.x,e.clientY-lookLast.y);lookLast={x:e.clientX,y:e.clientY}};look.onpointerup=look.onpointercancel=look.onlostpointercapture=e=>{if(e.pointerId===lookPointer){lookPointer=null;lookLast=null}};
function hold(selector,key){const b=$(selector);b.onpointerdown=e=>{if(view!=='playing')return;e.preventDefault();b.setPointerCapture(e.pointerId);input[key]=true;b.classList.add('active');send()};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>{input[key]=false;b.classList.remove('active');send()}}
hold('#fire','fire');hold('#sprint','sprint');$('#aim').onclick=()=>{input.aim=!input.aim;$('#aim').classList.toggle('active',input.aim);send()};$('#reload').onclick=()=>game?.reload();
window.addEventListener('keydown',e=>{if(e.code==='Escape'){if(view==='paused')$('#resume').click();else pause();return}if(view!=='playing')return;if(['KeyW','KeyA','KeyS','KeyD','Space','ShiftLeft','ShiftRight','KeyR'].includes(e.code)){e.preventDefault();keys.add(e.code);if(e.code==='Space')input.fire=true;if(e.code.startsWith('Shift'))input.sprint=true;if(e.code==='KeyR'&&!e.repeat)game.reload();send()}});window.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='Space')input.fire=false;if(e.code.startsWith('Shift'))input.sprint=false;send()});window.addEventListener('blur',()=>{release();pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){release();pause()}});
function onState(s){lastState=s;const health=Math.max(0,Math.round(s.health||0));$('#health-value').textContent=health;$('#health-fill').style.width=health+'%';$('#health-fill').style.background=health<30?'#e38970':'#d5dc62';$('#score').textContent=String(Math.floor(s.score||0)).padStart(4,'0');$('#kills').textContent=(s.kills||0)+' ABSCHÜSSE';const t=Math.max(0,Math.ceil(s.time||0));$('#timer').textContent=`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;$('#ammo').textContent=s.ammo??0;$('#reserve').textContent=s.reserve??0;$('#weapon-name').textContent=weaponId==='falcon'?'FALCON / KARABINER':'VX-7 / STURMGEWEHR';$('#reload-status').textContent=s.reloading?'LÄDT NACH …':s.ammo===0?'NACHLADEN ↻':'';const capture=typeof s.capture==='number'?s.capture:(s.capture?.progress||0);$('#capture-fill').style.width=Math.min(100,capture<=1?capture*100:capture)+'%';$('#objective-status').textContent=capture>0?'Kontrollpunkt aktiv · Punkte sichern':'Bewege dich zur gelben Markierung';$('#respawn').hidden=s.phase!=='respawn';if(s.phase==='finished'){release();setScreen('finished');$('#result-score').textContent=Math.floor(s.score||0);$('#result-kills').textContent=s.kills||0;$('#result-deaths').textContent=s.deaths||0}else if(s.phase==='respawn'&&view==='playing'){release();view='respawn'}else if(s.phase==='playing'&&view==='respawn')view='playing'}
function onEvent(e){sound(e.type);if(['hit','kill'].includes(e.type)){clearTimeout(markerTimer);$('#hitmarker').style.opacity=1;$('#hitmarker').style.color=e.type==='kill'?'#d5dc62':'#fff';markerTimer=setTimeout(()=>$('#hitmarker').style.opacity=0,130)}if(e.type==='hurt'){clearTimeout(damageTimer);$('#damage').style.opacity=1;damageTimer=setTimeout(()=>$('#damage').style.opacity=0,250)}if(e.text&&e.type!=='shoot'&&e.type!=='hit'){const div=document.createElement('div');div.textContent=e.text;$('#events').prepend(div);while($('#events').children.length>3)$('#events').lastElementChild.remove();setTimeout(()=>div.remove(),3500)}}
$('#start').disabled=true;try{const {initGame}=await import('./fps-engine.js');game=initGame($('#world'),{onState,onEvent});$('#boot-status').textContent='BEREIT / 120 SEKUNDEN / OFFLINE';$('#start').disabled=false;Object.defineProperty(window,'__sops',{value:Object.freeze({getState:()=>game.getState(),getDebugState:()=>game.getDebugState()}),writable:false})}catch(e){console.error(e);$('#boot-status').textContent='3D-Start fehlgeschlagen. Aktuelle Android System WebView und WebGL2 erforderlich.';$('#boot-status').classList.add('error')}
